package it.pagopa.posgw.common.domain.v1

import it.pagopa.posgw.common.annotation.ValueObject
import java.util.UUID

/**
 * Identifies a group of related operations.
 *
 * @param value UUID used as the correlation identifier; a random UUID is generated by default
 */
@ValueObject
@JvmInline
value class CorrelationId(val value: UUID = UUID.randomUUID()) {
    companion object {
        /**
         * Creates a correlation ID from a UUID string.
         *
         * @param uuid string representation of the UUID
         * @return correlation ID containing the parsed UUID
         * @throws IllegalArgumentException if [uuid] is not a valid UUID string
         */
        fun of(uuid: String) = CorrelationId(UUID.fromString(uuid))
    }
}
